import re

OPENER = re.compile(r'```([a-z]+)?\Z')


def scan(lines):
    """Scan an iterable of complete lines, retaining their original endings.

    Return dictionaries with line, language, content, and closed fields.
    """
    blocks = []
    content = None
    opener_line = None
    language = None

    for number, line in enumerate(lines, 1):
        if line.endswith('\r\n'):
            text = line[:-2]
        elif line.endswith(('\n', '\r')):
            text = line[:-1]
        else:
            text = line

        if content is None:
            match = OPENER.fullmatch(text)
            if match:
                opener_line = number
                language = match.group(1)
                content = []
        elif text == '```':
            blocks.append({
                'line': opener_line,
                'language': language,
                'content': ''.join(content),
                'closed': True,
            })
            content = None
        else:
            content.append(line)

    if content is not None:
        blocks.append({
            'line': opener_line,
            'language': language,
            'content': ''.join(content),
            'closed': False,
        })
    return blocks
```

