```python
import re

OPENER = re.compile(r'```([a-z]+)?\Z')


def scan(lines):
    """Scan an iterable of complete lines with their original endings intact.

    Return dicts containing the opener's one-based line number, language,
    exact content, and whether the block was closed.
    """
    blocks = []
    inside = False
    content = None
    opener_line = None

    for number, line in enumerate(lines, 1):
        if line.endswith('\r\n'):
            text = line[:-2]
        elif line.endswith(('\n', '\r')):
            text = line[:-1]
        else:
            text = line

        if not inside:
            match = OPENER.fullmatch(text)
            if match:
                inside = True
                opener_line = number
                content = [] if match.group(1) == 'python' else None
        elif text == '```':
            if content is not None:
                blocks.append({
                    'line': opener_line,
                    'language': 'python',
                    'content': ''.join(content),
                    'closed': True,
                })
            inside = False
            content = None
        elif content is not None:
            content.append(line)

    if inside and content is not None:
        blocks.append({
            'line': opener_line,
            'language': 'python',
            'content': ''.join(content),
            'closed': False,
        })
    return blocks
