import unittest


def record(line, content, closed=True):
    return {'line': line, 'language': 'python',
            'content': content, 'closed': closed}


class ScannerTests(unittest.TestCase):
    def test_empty_and_ordinary_input(self):
        self.assertEqual(scan([]), [])
        self.assertEqual(scan(['hello\n', '> ```python\n',
                               ' ```python\n', '```python \n',
                               '```Python\n', '```python3\n',
                               '```python-test\n']), [])

    def test_empty_and_multiple_python_blocks(self):
        lines = ['```python\n', '```\n', 'outside\n',
                 '```python\n', 'x\n', '```\n']
        self.assertEqual(scan(lines), [record(1, ''), record(4, 'x\n')])

    def test_other_blocks_suppress_python_looking_openers(self):
        lines = ['```ruby\n', '```python\n', "print('hello')\n",
                 '```\n', '```\n']
        self.assertEqual(scan(lines), [])

    def test_untagged_block_also_suppresses_opener(self):
        self.assertEqual(scan(['```\n', '```python\n', '```\n']), [])

    def test_exact_content_and_mixed_endings(self):
        lines = ['```python\r\n', '  alpha  \r\n', '\tβ\r',
                 '```ruby\n', '> ```\n', ' ```\n', '``` \n',
                 '```\r']
        self.assertEqual(scan(lines), [record(
            1, '  alpha  \r\n\tβ\r```ruby\n> ```\n ```\n``` \n')])

    def test_unclosed_python_content_and_empty_block(self):
        self.assertEqual(scan(['```python\n', 'data\r\n', 'end']),
                         [record(1, 'data\r\nend', False)])
        self.assertEqual(scan(['```python']), [record(1, '', False)])

    def test_unclosed_non_python_blocks_are_ignored(self):
        self.assertEqual(scan(['```ruby\n', '```python\n']), [])
        self.assertEqual(scan(['```\n', 'content']), [])

    def test_bare_fence_after_closer_opens_new_block(self):
        lines = ['```python\n', '```\n', '```\n',
                 '```python\n', '```\n', '```python\n']
        self.assertEqual(scan(lines), [record(1, ''), record(6, '', False)])

    def test_closer_without_final_newline(self):
        self.assertEqual(scan(['```python\n', 'x\n', '```']),
                         [record(1, 'x\n')])


if __name__ == '__main__':
    unittest.main()
```

